function generateAtmosphereField(time, latitude, windStrength):
    // Generate scaled Perlin noise
    noiseX = perlinNoise(x*scale, y*scale, time*speed)
    noiseY = perlinNoise(x*scale + 100, y*scale + 100, time*speed)

    // Apply curl operator to guarantee divergence-free
    // ∂v/∂x - ∂u/∂y = 0
    dxNoiseY = derivative(noiseY, x)
    dyNoiseX = derivative(noiseX, y)

    u = dxNoiseY * windStrength  // x-component of wind
    v = -dyNoiseX * windStrength // y-component of wind

    // Add latitude influence (simplified Coriolis effect)
    coriolisFactor = sin(latitude * π/180)
    u += coriolisFactor * 0.3

    // Add large circulation cells
    hadleyCell = sin(y * π/hadleyHeight) * hadleyStrength
    v += hadleyCell

    return vectorField(u, v)
